import{_ as s,C as i,c as o,o as e,a2 as d,b as n,w as r,a as l,G as c,a3 as u}from"./chunks/framework.DkPtUiZm.js";const L=JSON.parse('{"title":"Matrice de couverture web et mobile","description":"","frontmatter":{},"headers":[],"relativePath":"contribuer/parite-web-mobile.md","filePath":"contribuer/parite-web-mobile.md","lastUpdated":1794238461000}'),p={name:"contribuer/parite-web-mobile.md"};function m(b,t,h,v,g,f){const a=i("Mermaid");return e(),o("div",null,[t[1]||(t[1]=d('<h1 id="matrice-de-couverture-web-et-mobile" tabindex="-1">Matrice de couverture web et mobile <a class="header-anchor" href="#matrice-de-couverture-web-et-mobile" aria-label="Permalink to &quot;Matrice de couverture web et mobile&quot;">​</a></h1><p>État du code au <strong>9 novembre 2026</strong>, avec le lot listes et parcours métier mobiles. Cette matrice compare les <strong>115 modules publics</strong> exportés par <code>@sia-ui/react-web</code> au socle <code>@sia-ui/react-native</code> et à son adaptateur Expo Router. Un module peut exporter plusieurs composants, des types ou des fonctions : ce nombre n’est ni un nombre de composants individuels ni un pourcentage de parité fonctionnelle.</p><h2 id="sources-et-methode" tabindex="-1">Sources et méthode <a class="header-anchor" href="#sources-et-methode" aria-label="Permalink to &quot;Sources et méthode&quot;">​</a></h2><ul><li><a href="https://github.com/BeatJo/sia-ui/blob/main/packages/react-web/src/index.ts" target="_blank" rel="noreferrer">Exports publics web</a>.</li><li><a href="https://github.com/BeatJo/sia-ui/blob/main/packages/react-native/src/index.ts" target="_blank" rel="noreferrer">Exports publics natifs</a> et <a href="https://github.com/BeatJo/sia-ui/blob/main/packages/react-native/src/expo-router.tsx" target="_blank" rel="noreferrer">adaptateur Expo</a>.</li><li>Contrats et implémentations des champs, formulaires, navigation, modales et états natifs ; <a href="./../guides/react-native.html">guide mobile</a>, <a href="./../guides/formulaires-mobiles.html">formulaires mobiles</a> et <a href="./../guides/navigation-mobile-expo-router.html">navigation/session</a>.</li></ul><p>La comparaison porte sur l’existence d’une API publique et sa responsabilité, pas sur la seule présence d’un dessin dans la démo. Un écran d’exemple, une composition manuelle ou une fonction headless ne compte pas comme un composant natif livré. Les exports secondaires d’un module web sont à examiner lors de son portage ; cette matrice ne prétend pas auditer chaque prop, événement ou variante.</p><table tabindex="0"><thead><tr><th>Statut</th><th>Signification</th></tr></thead><tbody><tr><td><strong>Disponible</strong></td><td>Un équivalent natif couvre la responsabilité principale ; cela ne signifie ni API identique ni validation complète sur téléphone.</td></tr><tr><td><strong>Partiel</strong></td><td>Une partie du besoin existe, dans un composant plus limité, une composition ou une intégration de démo. Les écarts sont indiqués.</td></tr><tr><td><strong>À créer</strong></td><td>Aucun équivalent public natif dédié ; travail <strong>prévu</strong>, non livré.</td></tr><tr><td><strong>À adapter</strong></td><td>Le besoin doit être repensé pour le tactile, les primitives natives ou le format d’écran ; travail <strong>prévu</strong>, décision ou portage encore à faire.</td></tr></tbody></table><p><strong>Tous les composants natifs restent expérimentaux.</strong> Les tests de comportement, exports Android/iOS/web et essais dans le navigateur ne prouvent pas les gestes, le clavier, les zones sûres, les lecteurs d’écran ou les performances sur appareil. Les retours utilisateur doivent être rattachés à un appareil, un système, un mode et une révision avant de déclarer une fonctionnalité validée sur téléphone.</p><h2 id="bilan-par-statut" tabindex="-1">Bilan par statut <a class="header-anchor" href="#bilan-par-statut" aria-label="Permalink to &quot;Bilan par statut&quot;">​</a></h2><ul><li><strong>Disponible : 41 modules web.</strong></li><li><strong>Partiel : 22 modules web.</strong></li><li><strong>À créer : 32 modules web.</strong></li><li><strong>À adapter : 20 modules web.</strong></li></ul><p>Les lots ci-dessous sont des <strong>priorités proposées</strong>, pas des engagements de livraison ni des dates. <code>V</code> concerne la consolidation de l’existant ; <code>L1</code> à <code>L5</code> identifient le premier lot où traiter le sujet. Un module partiel peut nécessiter plusieurs incréments.</p><h2 id="matrice-detaillee" tabindex="-1">Matrice détaillée <a class="header-anchor" href="#matrice-detaillee" aria-label="Permalink to &quot;Matrice détaillée&quot;">​</a></h2><h3 id="fondations-visuelles-et-presentation" tabindex="-1">Fondations visuelles et présentation <a class="header-anchor" href="#fondations-visuelles-et-presentation" aria-label="Permalink to &quot;Fondations visuelles et présentation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module web</th><th>Statut mobile</th><th>Équivalent ou base actuelle</th><th>Écart réel / adaptation utile</th><th>Lot</th></tr></thead><tbody><tr><td><code>Typography</code></td><td>Partiel</td><td>Text</td><td>Variantes body/title/caption/display/heading/subtitle/code ; pas de portage complet des exports typographiques web.</td><td>L1</td></tr><tr><td><code>Button</code></td><td>Disponible</td><td>Button</td><td>Action, variantes, tailles, chargement et animations ; les props DOM deviennent des props Pressable.</td><td>V</td></tr><tr><td><code>IconButton</code></td><td>Disponible</td><td>IconButton</td><td>Nom accessible obligatoire, icône et comportements Button réutilisés.</td><td>V</td></tr><tr><td><code>Icons</code></td><td>À adapter</td><td>Icônes fournies par l’application</td><td>La démo utilise Ionicons ; aucune collection SIA native exportée. Définir un contrat commun sans imposer une dépendance.</td><td>L1</td></tr><tr><td><code>BrandIcon</code></td><td>À créer</td><td>—</td><td>Créer un rendu de marque natif configurable ; le logo de la démo est une Image locale.</td><td>L3</td></tr><tr><td><code>Card</code></td><td>Disponible</td><td>Card et parties composables</td><td>CardHeader, CardBody et CardFooter sont exportés ; title/description existants restent disponibles.</td><td>V</td></tr><tr><td><code>Badge</code></td><td>Disponible</td><td>Badge</td><td>Tons, variantes soft/solid/outline et tailles ; vérifier contraste et grands textes sur appareil.</td><td>V</td></tr><tr><td><code>Avatar</code></td><td>Disponible</td><td>Avatar</td><td>Image, échec avec repli par initiales/contenu, nom accessible et taille.</td><td>V</td></tr><tr><td><code>Label</code></td><td>Partiel</td><td>Labels intégrés aux champs</td><td>Pas de Label autonome ; l’association accessible est intégrée à Input et aux champs.</td><td>L2</td></tr><tr><td><code>Divider</code></td><td>Disponible</td><td>Divider</td><td>Séparateur horizontal/vertical avec style natif.</td><td>V</td></tr><tr><td><code>Container</code></td><td>Partiel</td><td>View et AppShell</td><td>La composition est possible ; aucun Container SIA natif dédié aux largeurs et espacements.</td><td>L3</td></tr><tr><td><code>AspectRatio</code></td><td>À adapter</td><td>View.style.aspectRatio</td><td>La primitive RN existe ; décider si un wrapper SIA apporte une valeur avant de le créer.</td><td>L5</td></tr><tr><td><code>ScrollArea</code></td><td>À adapter</td><td>ScrollView / FlatList</td><td>Employer les primitives natives et la virtualisation ; ne pas copier les scrollbars DOM.</td><td>L3</td></tr><tr><td><code>ColorModeToggle</code></td><td>Partiel</td><td>SiaNativeProvider et commandes de la démo</td><td>Le thème système/clair/sombre existe ; pas de commande autonome ColorModeToggle.</td><td>L1</td></tr></tbody></table><h3 id="champs-et-selection" tabindex="-1">Champs et sélection <a class="header-anchor" href="#champs-et-selection" aria-label="Permalink to &quot;Champs et sélection&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module web</th><th>Statut mobile</th><th>Équivalent ou base actuelle</th><th>Écart réel / adaptation utile</th><th>Lot</th></tr></thead><tbody><tr><td><code>Input</code></td><td>Disponible</td><td>Input</td><td>Label, aide, erreurs rouges, ref, clavier et focus ; le contrat utilise TextInputProps plutôt que les props HTML.</td><td>V</td></tr><tr><td><code>PasswordInput</code></td><td>Disponible</td><td>PasswordInput</td><td>Visibilité et ref natives ; vérifier le curseur et le clavier sur Android/iOS.</td><td>V</td></tr><tr><td><code>Checkbox</code></td><td>Disponible</td><td>Checkbox</td><td>États coché/non coché/mixte, erreurs et désactivation ; activation tactile à valider sur appareil.</td><td>V</td></tr><tr><td><code>Switch</code></td><td>Disponible</td><td>Switch</td><td>Identité SIA, tailles, focus et animations ; bascule par appui, sans glissement latéral du pouce.</td><td>V</td></tr><tr><td><code>RadioGroup</code></td><td>Disponible</td><td>RadioGroup</td><td>Choix unique et options désactivées ; pas d’export Radio individuel comparable au web.</td><td>V</td></tr><tr><td><code>Select</code></td><td>Disponible</td><td>Select dans BottomSheet</td><td>Recherche locale ou distante annulable, liste virtualisée et réessai ; pas de pagination distante.</td><td>V</td></tr><tr><td><code>MultiSelect</code></td><td>Disponible</td><td>MultiSelect</td><td>Choix multiples, résumé des libellés et confirmation dans une feuille.</td><td>V</td></tr><tr><td><code>Autocomplete</code></td><td>Disponible</td><td>Autocomplete</td><td>Suggestions distantes annulables et valeur libre optionnelle dans une feuille ; pas de menu DOM.</td><td>V</td></tr><tr><td><code>ReferenceSelect</code></td><td>À créer</td><td>—</td><td>Sélection d’une entité distante avec chargement, erreur et conservation de valeur.</td><td>L3</td></tr><tr><td><code>SearchInput</code></td><td>Partiel</td><td>SearchInput</td><td>Effacement et recherche sur validation ; temporisation réseau à composer.</td><td>V</td></tr><tr><td><code>Textarea</code></td><td>Disponible</td><td>Textarea</td><td>Contrôle multiligne, hauteur minimale et retour à la ligne ; pas de redimensionnement DOM.</td><td>V</td></tr><tr><td><code>InputNumber</code></td><td>Disponible</td><td>InputNumber</td><td>Brouillon intermédiaire, bornes, pas, précision et boutons masquables ; formatage local avancé absent.</td><td>V</td></tr><tr><td><code>CurrencyInput</code></td><td>Partiel</td><td>CurrencyInput</td><td>Précision et suffixe de devise ; formatage local complet des séparateurs à compléter.</td><td>V</td></tr><tr><td><code>PhoneInput</code></td><td>Partiel</td><td>PhoneInput</td><td>Normalisation via pays configurés et conservation des saisies invalides ; sélecteur de pays absent.</td><td>V</td></tr><tr><td><code>OtpInput</code></td><td>Partiel</td><td>OtpInput</td><td>Champ unique avec collage nettoyé et suggestion système ; cases séparées non portées.</td><td>V</td></tr><tr><td><code>TagsInput</code></td><td>À créer</td><td>—</td><td>Ajout, suppression, doublons et débordement des étiquettes sur petit écran.</td><td>L2</td></tr><tr><td><code>Slider</code></td><td>À créer</td><td>—</td><td>La logique headless de slider existe ; le rendu tactile simple/plage et l’accessibilité restent à implémenter.</td><td>L2</td></tr><tr><td><code>Rating</code></td><td>À créer</td><td>—</td><td>Notation tactile, lecture seule et annonce de la valeur.</td><td>L2</td></tr><tr><td><code>Toggle</code></td><td>À créer</td><td>—</td><td>Un bouton d’état pressé distinct du Switch ; ajouter son contrat et ses états accessibles.</td><td>L2</td></tr><tr><td><code>ColorPicker</code></td><td>À créer</td><td>—</td><td>Une saisie hexadécimale dans la démo ne constitue pas un sélecteur de couleur réutilisable.</td><td>L4</td></tr><tr><td><code>FileUpload</code></td><td>Partiel</td><td>FileUpload et NativeFilePickerProvider</td><td>Sélection injectable, type/taille/nombre, retrait, annulation et erreurs ; transfert et progression réseau non inclus.</td><td>V</td></tr><tr><td><code>ImageUpload</code></td><td>Partiel</td><td>ImageUpload</td><td>Photothèque/caméra via adaptateur, aperçu et limites ; recadrage/compression et transfert non inclus.</td><td>V</td></tr><tr><td><code>SecretFields</code></td><td>À créer</td><td>—</td><td>Masquage des secrets, remplacement et conservation d’une valeur existante ; PasswordInput ne couvre pas le workflow.</td><td>L3</td></tr></tbody></table><h3 id="formulaires-et-parcours" tabindex="-1">Formulaires et parcours <a class="header-anchor" href="#formulaires-et-parcours" aria-label="Permalink to &quot;Formulaires et parcours&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module web</th><th>Statut mobile</th><th>Équivalent ou base actuelle</th><th>Écart réel / adaptation utile</th><th>Lot</th></tr></thead><tbody><tr><td><code>Field</code></td><td>Partiel</td><td>Field / FormField</td><td>Dispatcher natif de 21 types, rendu personnalisé et visibilité ; autres champs web à porter.</td><td>V</td></tr><tr><td><code>FormField</code></td><td>Disponible</td><td>FormField</td><td>Liaison adaptateur, événements TextInput, références stables, erreurs et états ; types natifs uniquement.</td><td>V</td></tr><tr><td><code>Form</code></td><td>Partiel</td><td>Form et FormContainer</td><td>Déclaratif local/externe, groupes, validation, premier invalide et barre clavier ; tous les champs web ne sont pas portés.</td><td>V</td></tr><tr><td><code>Steps</code></td><td>Disponible</td><td>Steps</td><td>États, connecteurs animés, orientation, étape contrôlée et callback ; validation externe et statusLabels traduisibles.</td><td>V</td></tr><tr><td><code>UnsavedChangesGuard</code></td><td>Partiel</td><td>SiaExpoUnsavedChangesGuard</td><td>Retour et shell protégés ; utiliser useSiaExpoNavigation pour les liens personnalisés.</td><td>V</td></tr></tbody></table><h3 id="navigation-structure-et-session" tabindex="-1">Navigation, structure et session <a class="header-anchor" href="#navigation-structure-et-session" aria-label="Permalink to &quot;Navigation, structure et session&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module web</th><th>Statut mobile</th><th>Équivalent ou base actuelle</th><th>Écart réel / adaptation utile</th><th>Lot</th></tr></thead><tbody><tr><td><code>AppShell</code></td><td>Disponible</td><td>AppShell et SiaExpoLayout</td><td>Disposition responsive, clavier, zones sûres et slots ; routes privées via l’adaptateur Expo optionnel.</td><td>V</td></tr><tr><td><code>Sidebar</code></td><td>Disponible</td><td>Sidebar</td><td>Arbre, permissions, rail, sous-menus et variante flottante ; tester largeur, focus et grands textes sur appareil.</td><td>V</td></tr><tr><td><code>Tabs</code></td><td>Disponible</td><td>Tabs, TabsList, TabsTrigger, TabsContent</td><td>Vues contrôlées/locales, panneaux conservés avec fondu/glissement et fond animé ; navigation externe par flèches/Home/End encore à compléter.</td><td>V</td></tr><tr><td><code>Accordion</code></td><td>Disponible</td><td>Accordion</td><td>Hook partagé, single/multiple, variantes, disabled, contenu conservé et hauteur animée ; gestes et focus natifs à valider.</td><td>V</td></tr><tr><td><code>Breadcrumb</code></td><td>À adapter</td><td>—</td><td>Sur mobile, privilégier Retour et titre ; un fil d’Ariane compact reste un besoin distinct sur tablette.</td><td>L5</td></tr><tr><td><code>PageHeader</code></td><td>Disponible</td><td>PageHeader</td><td>Titre, description, retour et actions adaptatives ; rendus natifs, sans contrat DOM.</td><td>V</td></tr><tr><td><code>AuthLayout</code></td><td>Partiel</td><td>Écran sign-in de la démo</td><td>La page fonctionne dans la démo ; aucun AuthLayout natif générique exporté.</td><td>L3</td></tr><tr><td><code>AccountMenu</code></td><td>Partiel</td><td>Page Compte et footer de la démo</td><td>Session et déconnexion sont intégrées ; pas de menu de compte réutilisable.</td><td>L3</td></tr><tr><td><code>RequireSession</code></td><td>Disponible</td><td>RequireSession</td><td>Même SessionStore SIA : vérification, profil incomplet, refus et callbacks ; ne constitue pas une autorisation serveur.</td><td>V</td></tr><tr><td><code>PermissionGate</code></td><td>Disponible</td><td>PermissionGate</td><td>Évaluateur injecté, règle déclarée refusée sans évaluateur ; autorisation serveur toujours nécessaire.</td><td>V</td></tr><tr><td><code>PermissionMatrix</code></td><td>À créer</td><td>—</td><td>Édition de droits sur mobile sous forme de sections/listes ; éviter une grille horizontale trop large.</td><td>L5</td></tr></tbody></table><h3 id="couches-flottantes-et-actions-contextuelles" tabindex="-1">Couches flottantes et actions contextuelles <a class="header-anchor" href="#couches-flottantes-et-actions-contextuelles" aria-label="Permalink to &quot;Couches flottantes et actions contextuelles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module web</th><th>Statut mobile</th><th>Équivalent ou base actuelle</th><th>Écart réel / adaptation utile</th><th>Lot</th></tr></thead><tbody><tr><td><code>Modal</code></td><td>Disponible</td><td>Modal</td><td>Ouverture contrôlée, footer, clavier, Retour et défilement ; APIs et garanties de focus DOM non transposables telles quelles.</td><td>V</td></tr><tr><td><code>Drawer</code></td><td>Partiel</td><td>Tiroir de navigation AppShell / BottomSheet</td><td>Pas de Drawer autonome générique aux quatre positions avec ref impérative ; le tiroir AppShell sert à la navigation.</td><td>L3</td></tr><tr><td><code>Overlay</code></td><td>Partiel</td><td>Couches internes de Modal et NativeThemeScope</td><td>Pas de composant public Overlay natif équivalent ; étudier empilement, fonds et interactions entre plusieurs couches.</td><td>L1</td></tr><tr><td><code>ConfirmDialog</code></td><td>Disponible</td><td>ConfirmDialog</td><td>Action asynchrone verrouillée, erreur réessayable, ton danger et confirmation textuelle.</td><td>V</td></tr><tr><td><code>DropdownMenu</code></td><td>À adapter</td><td>—</td><td>Menu d’actions tactile en feuille ou menu ancré ; éviter les interactions reposant sur le survol.</td><td>L2</td></tr><tr><td><code>Popover</code></td><td>À adapter</td><td>—</td><td>Choisir menu ancré ou feuille selon l’écran ; mesure, repositionnement et clavier à traiter côté natif.</td><td>L3</td></tr><tr><td><code>Tooltip</code></td><td>À adapter</td><td>accessibilityLabel / accessibilityHint</td><td>Les noms accessibles existent ; un tooltip visuel tactile par appui long reste absent.</td><td>L5</td></tr><tr><td><code>HoverCard</code></td><td>À adapter</td><td>—</td><td>Le survol ne convient pas au téléphone ; préférer un aperçu sur appui ou une feuille de détail.</td><td>L5</td></tr><tr><td><code>CommandPalette</code></td><td>À adapter</td><td>—</td><td>Recherche globale/actions en feuille sur téléphone ; raccourcis clavier surtout pour tablette et clavier externe.</td><td>L5</td></tr><tr><td><code>Tour</code></td><td>À adapter</td><td>—</td><td>Mesure des cibles, défilement, changements de route et accessibilité à concevoir pour le guidage mobile.</td><td>L5</td></tr></tbody></table><h3 id="retours-utilisateur-et-etats" tabindex="-1">Retours utilisateur et états <a class="header-anchor" href="#retours-utilisateur-et-etats" aria-label="Permalink to &quot;Retours utilisateur et états&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module web</th><th>Statut mobile</th><th>Équivalent ou base actuelle</th><th>Écart réel / adaptation utile</th><th>Lot</th></tr></thead><tbody><tr><td><code>Alert</code></td><td>Disponible</td><td>Alert</td><td>Message sémantique, ton, action et fermeture contrôlée ; annoncer le contenu sans masquer les boutons.</td><td>V</td></tr><tr><td><code>Toast</code></td><td>Disponible</td><td>Toast contrôlé et Toaster partagé</td><td>Pile, mises à jour, actions et placements reliés au store existant ; un hôte par store, pas de surcouche au-dessus des fenêtres Modal natives.</td><td>V</td></tr><tr><td><code>Spinner</code></td><td>Disponible</td><td>Spinner</td><td>Dessins SIA ring/double-ring/dots, cinq tailles xs–xl, tons et current via contexte natif ; arrêt en arrière-plan et mouvement réduit.</td><td>V</td></tr><tr><td><code>Skeleton</code></td><td>Disponible</td><td>Skeleton</td><td>Dimensions, rayon et pulsation ; statique lorsque le mouvement est réduit.</td><td>V</td></tr><tr><td><code>Progress</code></td><td>Disponible</td><td>Progress</td><td>Remplissage borné animé/interruptible, maximum, attente indéterminée et valeur accessible.</td><td>V</td></tr><tr><td><code>EmptyState</code></td><td>Partiel</td><td>StateScreen</td><td>Titre, description et action disponibles ; pas de composant spécifique ni de parité de ses slots web.</td><td>L3</td></tr><tr><td><code>ErrorState</code></td><td>Partiel</td><td>StateScreen et SiaExpoErrorBoundary</td><td>Erreur et réessai disponibles ; conserver une séparation entre l’erreur de page et celle d’une requête.</td><td>L3</td></tr><tr><td><code>AsyncState</code></td><td>Disponible</td><td>AsyncState</td><td>Chargement, vide, erreur, réessai et actions de repli composés avec StateScreen.</td><td>V</td></tr></tbody></table><h3 id="dates-heures-et-agendas" tabindex="-1">Dates, heures et agendas <a class="header-anchor" href="#dates-heures-et-agendas" aria-label="Permalink to &quot;Dates, heures et agendas&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module web</th><th>Statut mobile</th><th>Équivalent ou base actuelle</th><th>Écart réel / adaptation utile</th><th>Lot</th></tr></thead><tbody><tr><td><code>Calendar</code></td><td>Disponible</td><td>Calendar</td><td>Calendrier SIA tactile, locale, année recherchable, jours indisponibles et fondu de mois ; navigation clavier de bureau à compléter.</td><td>V</td></tr><tr><td><code>DatePicker</code></td><td>Disponible</td><td>DatePicker</td><td>Jour civil contrôlé, bornes et brouillon ; mois complet ajusté à la feuille sans défilement interne.</td><td>V</td></tr><tr><td><code>DateTimePicker</code></td><td>Partiel</td><td>DateTimePicker</td><td>Vues date/heure distinctes avec brouillon local partagé ; fuseau métier et transitions heure d’été à traiter par l’application.</td><td>V</td></tr><tr><td><code>DateRangePicker</code></td><td>Disponible</td><td>DateRangePicker</td><td>Début/fin, ordre et bornes, remise au début si le second choix est antérieur ; validation métier des jours intérieurs externe.</td><td>V</td></tr><tr><td><code>TimePicker</code></td><td>Disponible</td><td>TimePicker</td><td>Heure HH:mm, bornes, pas de minutes et affichage 12/24 h ; contrôle SIA en feuille.</td><td>V</td></tr><tr><td><code>TimeRangePicker</code></td><td>À créer</td><td>—</td><td>Plage horaire et règles de franchissement/ordre à définir dans le contrat mobile.</td><td>L4</td></tr><tr><td><code>MonthPicker</code></td><td>À créer</td><td>—</td><td>Sélection mois/année compacte et accessible.</td><td>L4</td></tr><tr><td><code>WeekPicker</code></td><td>À créer</td><td>—</td><td>Sélection de semaine avec conventions de locale.</td><td>L4</td></tr><tr><td><code>YearPicker</code></td><td>À créer</td><td>—</td><td>Liste d’années virtualisée et bornes.</td><td>L4</td></tr><tr><td><code>MiniCalendar</code></td><td>À créer</td><td>—</td><td>Petit calendrier de contexte ; réutiliser le futur socle Calendar.</td><td>L4</td></tr><tr><td><code>EventCalendar</code></td><td>À adapter</td><td>—</td><td>Vue agenda/liste adaptée au petit écran ; la logique de calendrier headless existe déjà.</td><td>L5</td></tr><tr><td><code>EventManager</code></td><td>À créer</td><td>—</td><td>Composition agenda, détail et édition dépendante des futurs composants de date et de formulaire.</td><td>L5</td></tr><tr><td><code>DateRangeFilter</code></td><td>À créer</td><td>—</td><td>Filtre de période et raccourcis dépendants du futur DateRangePicker.</td><td>L4</td></tr></tbody></table><h3 id="listes-donnees-et-ecrans-metier" tabindex="-1">Listes, données et écrans métier <a class="header-anchor" href="#listes-donnees-et-ecrans-metier" aria-label="Permalink to &quot;Listes, données et écrans métier&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module web</th><th>Statut mobile</th><th>Équivalent ou base actuelle</th><th>Écart réel / adaptation utile</th><th>Lot</th></tr></thead><tbody><tr><td><code>Resource</code></td><td>Partiel</td><td>ResourceDefinitionCore partagé et defineResource natif</td><td>Métadonnées et conventions partagées ; champs et renderers restent propres à chaque plateforme.</td><td>V</td></tr><tr><td><code>CrudPage</code></td><td>Disponible</td><td>CrudPage natif</td><td>Liste, fiche, création/édition et suppression confirmée, droits et garde de saisie injectable ; pas de parité intégrale des props web.</td><td>V</td></tr><tr><td><code>DataTable</code></td><td>Partiel</td><td>ResourceList / FlatList</td><td>Cartes/lignes virtualisées, tri et pagination ; tableau multicolonnes tablette et actions en masse restent prévus.</td><td>V</td></tr><tr><td><code>FiltersBar</code></td><td>Disponible</td><td>FiltersBar</td><td>Recherche temporisée, filtres simples en feuille, annulation/validation et résumé ; filtres complexes non portés.</td><td>V</td></tr><tr><td><code>Pagination</code></td><td>Disponible</td><td>Pagination</td><td>Variantes compacte/numérotée et total ; pas de curseurs ou chargement infini.</td><td>V</td></tr><tr><td><code>Descriptions</code></td><td>Disponible</td><td>Descriptions</td><td>Paires libellé/valeur verticales ou en ligne, rendus natifs personnalisables.</td><td>V</td></tr><tr><td><code>EntityMeta</code></td><td>À créer</td><td>—</td><td>Métadonnées métier avec formatages partagés ; rendu mobile absent.</td><td>L3</td></tr><tr><td><code>AuditMeta</code></td><td>À créer</td><td>—</td><td>Création/modification/auteurs et informations d’audit dans une fiche.</td><td>L3</td></tr><tr><td><code>Statistic</code></td><td>À créer</td><td>—</td><td>Valeur, évolution et unité avec typographie adaptée.</td><td>L3</td></tr><tr><td><code>StatCard</code></td><td>À créer</td><td>—</td><td>Carte de statistique et actions composables ; le Card simple ne couvre pas ce contrat.</td><td>L3</td></tr><tr><td><code>KpiGrid</code></td><td>À adapter</td><td>—</td><td>Grille responsive ou liste de cartes ; éviter de conserver trop de colonnes sur téléphone.</td><td>L3</td></tr><tr><td><code>AmountDisplay</code></td><td>À créer</td><td>—</td><td>Les utilitaires de montants existent ; le composant natif de montant/devise reste absent.</td><td>L3</td></tr><tr><td><code>RelativeTime</code></td><td>À créer</td><td>—</td><td>Réutiliser les formatages et préciser la mise à jour au retour au premier plan.</td><td>L3</td></tr><tr><td><code>DurationDisplay</code></td><td>À créer</td><td>—</td><td>Formatage de durée partagé, mais aucun rendu natif dédié.</td><td>L3</td></tr><tr><td><code>Timeline</code></td><td>À créer</td><td>—</td><td>Chronologie verticale avec états et contenu accessible.</td><td>L3</td></tr><tr><td><code>Tree</code></td><td>À créer</td><td>—</td><td>Arbre de données et expansion ; la hiérarchie du Sidebar ne remplace pas un Tree générique.</td><td>L5</td></tr><tr><td><code>TreeSelect</code></td><td>À créer</td><td>—</td><td>Sélection hiérarchique en feuille, recherche et conservation des branches sélectionnées.</td><td>L5</td></tr><tr><td><code>Transfer</code></td><td>À adapter</td><td>—</td><td>Remplacer les deux colonnes par sélection et résumé des éléments choisis.</td><td>L5</td></tr><tr><td><code>Chart</code></td><td>À adapter</td><td>—</td><td>Choisir un moteur natif et des interactions tactiles ; pas d’import direct du rendu graphique web.</td><td>L5</td></tr><tr><td><code>QrCode</code></td><td>À adapter</td><td>—</td><td>Choisir un rendu natif compatible Expo ; génération, taille et partage à prévoir.</td><td>L5</td></tr></tbody></table><h3 id="editeurs-supervision-et-outils-specialises" tabindex="-1">Éditeurs, supervision et outils spécialisés <a class="header-anchor" href="#editeurs-supervision-et-outils-specialises" aria-label="Permalink to &quot;Éditeurs, supervision et outils spécialisés&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Module web</th><th>Statut mobile</th><th>Équivalent ou base actuelle</th><th>Écart réel / adaptation utile</th><th>Lot</th></tr></thead><tbody><tr><td><code>JsonView</code></td><td>À créer</td><td>—</td><td>Vue dépliable et copie dans le presse-papiers natif, avec gestion des gros objets.</td><td>L5</td></tr><tr><td><code>JsonEditor</code></td><td>À adapter</td><td>—</td><td>Évaluer texte simple, éditeur dédié ou édition structurée ; validation et clavier mobile restent nécessaires.</td><td>L5</td></tr><tr><td><code>MarkdownEditor</code></td><td>À adapter</td><td>—</td><td>Saisie, aperçu et barre d’actions tactiles ; ne pas importer un éditeur DOM.</td><td>L5</td></tr><tr><td><code>RichTextEditor</code></td><td>À adapter</td><td>—</td><td>Choix architectural natif ou WebView à documenter avant implémentation.</td><td>L5</td></tr><tr><td><code>ActivityLog</code></td><td>À créer</td><td>—</td><td>Liste virtualisée d’événements, pagination et filtres avec sources partagées.</td><td>L5</td></tr><tr><td><code>LogStream</code></td><td>À adapter</td><td>—</td><td>Limiter le rendu, gérer suivi/pause et cycle de vie mobile ; le temps réel partagé ne fournit pas l’UI.</td><td>L5</td></tr><tr><td><code>JobProgress</code></td><td>À créer</td><td>—</td><td>Étapes d’un traitement, progression, reprise et erreurs ; dépend notamment de Progress et de la logique partagée.</td><td>L5</td></tr><tr><td><code>LiveIndicator</code></td><td>À créer</td><td>—</td><td>Connexion et fraîcheur visibles ; le hook headless de statut temps réel peut être réutilisé.</td><td>L5</td></tr><tr><td><code>Timer</code></td><td>À créer</td><td>—</td><td>Minuteur avec recalcul après suspension ; ne pas supposer que les timers tournent normalement en arrière-plan.</td><td>L5</td></tr><tr><td><code>Countdown</code></td><td>À créer</td><td>—</td><td>Compte à rebours basé sur une échéance et recalcul au retour au premier plan.</td><td>L5</td></tr><tr><td><code>ResizablePanel</code></td><td>À adapter</td><td>—</td><td>Réserver les panneaux redimensionnables aux écrans larges ; sections/écrans sur téléphone.</td><td>L5</td></tr></tbody></table><h2 id="briques-natives-sans-module-web-du-meme-nom" tabindex="-1">Briques natives sans module web du même nom <a class="header-anchor" href="#briques-natives-sans-module-web-du-meme-nom" aria-label="Permalink to &quot;Briques natives sans module web du même nom&quot;">​</a></h2><p>Ces ajouts ne doivent pas être comptés comme des modules web supplémentaires. Ils répondent à des usages mobiles ou regroupent plusieurs responsabilités web.</p><table tabindex="0"><thead><tr><th>API native disponible</th><th>Relation avec le web</th><th>Ce qui reste à distinguer</th></tr></thead><tbody><tr><td>SiaNativeProvider, NativeThemeScope, useNativeTheme</td><td>Thème, locale et tokens communs</td><td>Distribution Uniwind, zones de portail et polices ; pas une API DOM interchangeable.</td></tr><tr><td>BottomBar</td><td>Navigation principale mobile ; pas d’export BottomBar web dans l’inventaire</td><td>Capsule/trait/minimal, styles, couleurs, badges, Plus et animations configurables sont livrés ; cela ne remplace pas Tabs dans une page.</td></tr><tr><td>BottomSheet</td><td>Besoin proche d’un Drawer web positionné en bas</td><td>Hauteur contrôlée, fermeture par poignée et primitives Modal sont livrées ; snap points et actions d’accessibilité par poignée sont livrés ; déplacement sur le contenu et arbitrage avancé des gestes restent <strong>prévus</strong>.</td></tr><tr><td>FormContainer, FormSection, KeyboardScrollView</td><td>Conteneur, regroupement et saisie libre avec clavier</td><td>Validation via FormAdapter et verrou d’envoi présents ; Form/Field génèrent et lient les 21 types natifs livrés ; les autres types web restent prévus.</td></tr><tr><td>StateScreen</td><td>Présentation commune de plusieurs états de page</td><td>404, refus, attente et action de reprise possibles ; AsyncState compose maintenant ces états pour les requêtes.</td></tr><tr><td>SiaExpoStack, SiaExpoLayout</td><td>Navigation protégée sur le SessionStore existant</td><td>Groupe privé, permission de route et retrait d’historique ; entrée optionnelle <code>@sia-ui/react-native/expo-router</code>.</td></tr><tr><td>useExpoSessionReturn, SiaExpoErrorBoundary</td><td>Reprise de route et erreur d’écran</td><td>Retour interne après connexion et réessai sont livrés ; aucune session parallèle n’est créée.</td></tr></tbody></table><h2 id="fondations-partagees-reutiliser-pas-annoncer-un-rendu-absent" tabindex="-1">Fondations partagées : réutiliser, pas annoncer un rendu absent <a class="header-anchor" href="#fondations-partagees-reutiliser-pas-annoncer-un-rendu-absent" aria-label="Permalink to &quot;Fondations partagées : réutiliser, pas annoncer un rendu absent&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Socle existant</th><th>Réutilisation possible</th><th>Limite actuelle</th></tr></thead><tbody><tr><td>Tokens de couleur, espacement, typographie et mouvement</td><td>Même identité, thèmes et vocabulaire de mouvement</td><td>Les animations et les composants restent des implémentations propres à chaque plateforme.</td></tr><tr><td>SessionStore, useSession et règles d’accès headless</td><td>Même session pour la navigation, l’expiration et les droits</td><td>Le stockage des secrets et les appels d’authentification réels restent ceux de l’application ; la démo native est locale.</td></tr><tr><td>FormAdapter, useLocalForm et validation partagée</td><td>Même contrat de valeurs/erreurs, validation asynchrone selon l’adaptateur</td><td>FormContainer ne génère pas les champs et n’injecte pas automatiquement disabled dans ses enfants.</td></tr><tr><td>Arbres de navigation, disclosure, pagination, recherche différée, accordéon et slider headless</td><td>Réutiliser les calculs et états sans DOM</td><td>L’existence du hook ne livre ni la gestuelle ni le composant natif correspondant.</td></tr><tr><td>Toast store et logique de temps réel</td><td>Réutiliser des annonces ou statuts</td><td>Toast contrôlé et Toaster connecté au store sont disponibles ; cycle de vie et empilement à valider sur appareil.</td></tr><tr><td>Utilitaires de montants, dates, téléphones et validation</td><td>Éviter de réécrire le formatage et les règles métier</td><td>Ne signifie pas qu’un champ ou un composant d’affichage natif existe.</td></tr><tr><td>Module API partagé</td><td>Brancher une application mobile à ses services</td><td>L’intégration réelle avec stockage, réseau et session doit être vérifiée dans l’application consommatrice.</td></tr><tr><td>Définition de ressource</td><td>Contrat commun de métadonnées avec adaptateurs de champs</td><td>Métadonnées et permissions extraites dans headless ; adaptateurs de champs propres au web et au natif.</td></tr></tbody></table><p>Le package natif ne doit pas importer les rendus de <code>@sia-ui/react-web</code>. Un contrat commun doit vivre dans une couche sans DOM ; les valeurs métier et la session peuvent être communes tout en gardant des interfaces adaptées au téléphone.</p>',35)),(e(),n(u,null,{default:r(()=>[c(a,{id:"mermaid-2509",class:"mermaid",graph:"flowchart%20TD%0A%20%20Tokens%5B%22Tokens%20communs%20existants%22%5D%20--%3E%20Web%5B%22Rendus%20web%20existants%22%5D%0A%20%20Tokens%20--%3E%20Native%5B%22Rendus%20natifs%20existants%22%5D%0A%20%20Shared%5B%22Session%2C%20formulaires%20et%20comportements%20headless%20existants%22%5D%20--%3E%20Web%0A%20%20Shared%20--%3E%20Native%0A%20%20Matrix%5B%22Matrice%20de%20couverture%22%5D%20--%3E%20Planned%5B%22Pr%C3%A9vu%20%3A%20contrats%20et%20adaptations%20manquants%22%5D%0A%20%20Planned%20-.-%3E%20Shared%0A%20%20Planned%20-.-%3E%20Mobile%5B%22Pr%C3%A9vu%20%3A%20composants%20et%20%C3%A9crans%20mobiles%22%5D%0A%20%20Native%20--%3E%20QA%5B%22Validation%20sur%20Android%20et%20iOS%22%5D%0A%20%20Mobile%20-.-%3E%20QA%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=d('<h2 id="ecarts-transversaux-a-suivre" tabindex="-1">Écarts transversaux à suivre <a class="header-anchor" href="#ecarts-transversaux-a-suivre" aria-label="Permalink to &quot;Écarts transversaux à suivre&quot;">​</a></h2><p>Ces points ne sont pas des modules supplémentaires et ne changent pas les comptes ci-dessus. Ils concernent plusieurs composants à la fois.</p><table tabindex="0"><thead><tr><th>Sujet</th><th>Existant</th><th>Travail restant / priorité</th></tr></thead><tbody><tr><td>Configuration par défaut</td><td>SiaNativeProvider transmet <code>defaults</code> au provider headless</td><td>Button, Badge, Spinner, Alert, Avatar, Skeleton, Progress, Steps, Tabs, Accordion, Input, Select, MultiSelect, Autocomplete et Calendar lisent leurs clés locales. Généralisation aux autres composants encore prévue ; ne pas annoncer une couverture globale.</td></tr><tr><td>Langues</td><td>Provider et plusieurs composants utilisent la locale partagée</td><td>Certains textes de l’adaptateur Expo et de la démo sont directement en français ; compléter l’internationalisation des textes de bibliothèque en L1/L2.</td></tr><tr><td>Personnalisation</td><td>Tokens, palettes locales et réglages détaillés de navigation</td><td>Les variantes, slots et props de personnalisation ne sont pas uniformes entre composants ; les vérifier lors de chaque portage.</td></tr><tr><td>Gestes et focus</td><td>Pressable, Animated, poignée PanResponder, premières annonces d’accessibilité</td><td>Focus initial/restauré, conflits de gestes, clavier et grands textes : validation V puis amélioration par composant.</td></tr><tr><td>Empilement des couches</td><td>Modal, BottomSheet et tiroir ont des implémentations natives</td><td>Vérifier les ouvertures imbriquées, le Retour et les annonces ; ne pas déduire la parité des garanties d’overlay DOM.</td></tr><tr><td>Distribution</td><td>Package natif, thème Uniwind et entrée Expo optionnelle</td><td>La CLI de copie des composants web ne distribue pas encore ces rendus natifs. Compatibilité annoncée limitée aux versions documentées du socle, pas à tout projet Expo/React Native.</td></tr></tbody></table><h2 id="ordre-de-realisation-et-avancement" tabindex="-1">Ordre de réalisation et avancement <a class="header-anchor" href="#ordre-de-realisation-et-avancement" aria-label="Permalink to &quot;Ordre de réalisation et avancement&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lot</th><th>Travail et avancement</th><th>Utilité et critère de sortie</th></tr></thead><tbody><tr><td>V — Consolider l’existant</td><td>Tester navigation, champs, clavier, zones sûres, Retour, expiration, 404 et mouvement réduit sur Android/iOS</td><td>Documenter appareil, système et révision ; fermer les anomalies observées sans présenter les exports comme des tests sur téléphone.</td></tr><tr><td>L1a — États et petites briques</td><td><strong>Socle livré</strong> : Badge, Avatar, Alert, Spinner, Skeleton, Progress, Divider, IconButton, parties Card, variantes Text et Toaster ; compléter les variantes et défauts transversaux</td><td>Construire un écran cohérent sans recréer les messages, les chargements ni une seconde API de notifications.</td></tr><tr><td>L1b — Organisation d’écran</td><td><strong>Livré</strong> : Steps, Tabs de contenu et Accordion ; compléter le clavier externe et les validations sur appareil</td><td>Démontrer un formulaire en étapes avec états current/done/upcoming/error, navigation contrôlée, sections et annonces accessibles. La validation métier reste dans le formulaire.</td></tr><tr><td>L1c — BottomSheet avancée</td><td><strong>Partiel livré</strong> : positions d’arrêt, hauteur bornée, poignée, durée et actions d’accessibilité ; agrandissement au clavier livré ; glissement sur le contenu prévu</td><td>Démontrer une sélection longue et un formulaire sans conflit de gestes, avec mouvement réduit. Choisir le moteur de gestes après essai de la solution existante ; aucune nouvelle dépendance n’est décidée ici.</td></tr><tr><td>L2 — Formulaires complets</td><td><strong>Socle livré</strong> : Field/Form, Select distant, MultiSelect, champs spécialisés, confirmation et protection Expo ; champs avancés et validation sur appareil à compléter</td><td>Démontrer saisie, recherche annulable, erreurs rouges, double envoi bloqué et abandon confirmé ; conserver focus, valeur et position lors des rendus.</td></tr><tr><td>L3 — Parcours métier</td><td>Contrat Resource sans DOM, liste/cartes virtualisées, filtres, pagination, détail et édition ; état asynchrone commun</td><td>Démontrer un parcours liste → détail → modification avec droits, actualisation, vide/erreur/réessai et conservation des filtres. Socle livré avec Contacts ; validation physique et compléments métier restent à effectuer.</td></tr><tr><td>L4 — Dates et fichiers</td><td><strong>Socle livré</strong> : calendrier, date/heure/période, sélection documents/images ; progression réseau, couleur et validations physiques à compléter</td><td>Valider valeurs, bornes, locale/fuseau selon le contrat, permissions système et annulation sur appareil. Choisir les dépendances compatibles avec Expo.</td></tr><tr><td>L5 — Besoins spécialisés</td><td>Graphiques, arbres, éditeurs, agendas avancés et supervision</td><td>Implémenter à partir d’un usage identifié ; ne pas reproduire automatiquement chaque interaction de bureau sur téléphone.</td></tr></tbody></table><p>Les lots sont découpables. L1a ne doit pas bloquer un premier Steps ou une amélioration ciblée de BottomSheet ; les dépendances réelles déterminent le détail des incréments. L5 constitue une réserve de besoins à arbitrer, pas un engagement de porter l’intégralité du catalogue web à l’identique.</p><h2 id="criteres-communs-a-chaque-composant-porte" tabindex="-1">Critères communs à chaque composant porté <a class="header-anchor" href="#criteres-communs-a-chaque-composant-porte" aria-label="Permalink to &quot;Critères communs à chaque composant porté&quot;">​</a></h2><ul><li>Conserver l’identité SIA : tokens, clair/sombre, couleurs personnalisées, messages d’erreur rouges et mêmes états sémantiques utiles.</li><li>Garder une API contrôlée cohérente avec le headless ; documenter les différences d’événements, refs et interactions propres à React Native.</li><li>Vérifier cibles tactiles, noms et valeurs accessibles, focus, grands textes, lecteur d’écran et navigation avec clavier externe lorsque pertinente.</li><li>Préserver la saisie et le défilement ; vérifier clavier logiciel, Retour Android, liens directs et cycle de vie de l’app lorsque le composant les utilise.</li><li>Respecter la réduction des animations, interrompre proprement les transitions et exposer les réglages utiles sans imposer des animations à l’application.</li><li>Ajouter des tests de comportement utiles, une démonstration et la documentation du même changement. Consigner séparément compilation et validation sur appareil.</li></ul><h2 id="maintenance-de-la-matrice" tabindex="-1">Maintenance de la matrice <a class="header-anchor" href="#maintenance-de-la-matrice" aria-label="Permalink to &quot;Maintenance de la matrice&quot;">​</a></h2><p>À chaque ajout ou changement de responsabilité publique : mettre à jour la ligne, son statut, les écarts encore présents et les preuves de validation. Ajouter une ligne lorsqu’un module web public apparaît ; mettre les API uniquement natives dans leur section dédiée. Le backlog indique précisément ce qui est effectivement livré ; cette matrice conserve aussi les besoins <strong>prévus</strong>.</p><p>Ne pas marquer un composant Disponible uniquement parce qu’il utilise le même nom, qu’une démo ressemble au web ou qu’un hook existe dans headless. En cas de nouveau sous-composant ou d’option majeure, reprendre l’examen du contrat avant de modifier son statut.</p><p>Le <a href="./../guides/composants-mobiles.html">guide du lot présentation et organisation</a> décrit les APIs livrées, les menus de la démo et les limites de gestes restantes.</p><p>Le <a href="./../guides/listes-parcours-mobiles.html">guide listes et parcours métier</a> décrit les APIs et les limites du socle L3 livré.</p>',13))])}const S=s(p,[["render",m]]);export{L as __pageData,S as default};
